@Nat.digits_def' : ∀ {b : ℕ}, 1 < b → ∀ {n : ℕ}, 0 < n → b.digits n = n % b :: b.digits (n / b)
@tsum_subtype : ∀ {α : Type u_1} {β : Type u_2} [inst : AddCommMonoid α] [inst_1 : TopologicalSpace α] (s : Set β)
  (f : β → α), ∑' (x : ↑s), f ↑x = ∑' (x : β), s.indicator f x
@tsum_eq_sum : ∀ {α : Type u_1} {β : Type u_2} [inst : AddCommMonoid α] [inst_1 : TopologicalSpace α] {f : β → α}
  {L : SummationFilter β} [L.LeAtTop] {s : Finset β}, (∀ b ∉ s, f b = 0) → ∑'[L] (b : β), f b = ∑ b ∈ s, f b
@Finset.sum_range_reflect : ∀ {δ : Type u_1} [inst : AddCommMonoid δ] (f : ℕ → δ) (n : ℕ),
  ∑ j ∈ Finset.range n, f (n - 1 - j) = ∑ j ∈ Finset.range n, f j
@Finset.sum_ite_eq : ∀ {ι : Type u_1} {M : Type u_2} [inst : AddCommMonoid M] [inst_1 : DecidableEq ι] (s : Finset ι)
  (a : ι) (b : ι → M), (∑ x ∈ s, if a = x then b x else 0) = if a ∈ s then b a else 0
@Finset.sum_comm : ∀ {α : Type u_1} {β : Type u_2} {γ : Type u_3} [inst : AddCommMonoid β] {s : Finset γ} {t : Finset α}
  {f : γ → α → β}, ∑ x ∈ s, ∑ y ∈ t, f x y = ∑ y ∈ t, ∑ x ∈ s, f x y

